// src/components/faq/FAQAccordion.tsx
import { FAQConfig } from '@/src/types/faq.types';
import FAQItem from './FAQItem';

interface FAQAccordionProps {
    locale: string;
    config: FAQConfig;
}

export default function FAQAccordion({ config }: FAQAccordionProps) {
    if (!config.faqs || config.faqs.length === 0) {
        return (
            <div className="container flex flex-col gap-5 py-5 md:py-10">
                <div className="text-center py-12">
                    <p className="text-gray-500">Henüz soru eklenmemiş.</p>
                </div>
            </div>
        );
    }

    return (
        <div className="container flex flex-col gap-5 py-5 md:py-10">
            <p className="text-ayda-blue text-lg md:text-xl text-center uppercase font-medium"></p>
            <div className="w-full flex flex-col gap-4">
                {config.faqs.map((faq) => (
                    <FAQItem
                        key={faq.id}
                        faqId={faq.id}
                        question={faq.question}
                        answer={faq.answer}
                    />
                ))}
            </div>
        </div>
    );
}